// Turns an esphome.spool_tap event into msg.tap, and drops repeat reads.
// A sticker at the edge of the PN532's range gets read several times in a row;
// only the first read of a tag on a reader within 4 s is processed. A repeat that
// arrives after the first one was answered gets the same answer again, so the
// reader doesn't sit white and time out.
const REPEAT_MS = 4000;

const ev = (msg.payload && msg.payload.event) || {};
const tag = String(ev.tag_id || '').trim().toUpperCase();
const location = String(ev.location || '').trim();
const reader = String(ev.reader || '').trim();
if (!tag || !location || !reader) {
    node.warn(`Ignoring spool tap with missing data: ${JSON.stringify(ev)}`);
    return [null, null];
}
const feedbackAction = `esphome.${reader.replace(/-/g, '_')}_feedback`;

const now = Date.now();
const last = flow.get('spoolTapLast') || {};
for (const k of Object.keys(last)) {
    if (now - last[k].t > 60000) delete last[k];
}
const key = `${reader}|${tag}`;
const prev = last[key];
if (prev && now - prev.t < REPEAT_MS) {
    flow.set('spoolTapLast', last);
    if (prev.result === null) return [null, null]; // first read still in progress
    return [null, { payload: { action: feedbackAction, data: { success: prev.result } } }];
}
last[key] = { t: now, result: null };
flow.set('spoolTapLast', last);

msg.tap = { tag, location, reader, feedbackAction };
node.status({ fill: 'blue', shape: 'dot', text: `${tag} @ ${location}` });
return [msg, null];

// Finds the spool for msg.tap.tag and builds the Spoolman update.
// Normal tap: the spool whose nfc_uid matches gets the reader's location.
// Enroll mode (input_number.spool_enroll_id > 0): that spool gets this tag as its
// nfc_uid and moves to the reader's location.
// Output 1: PATCH request for Spoolman. Output 2: failure, with msg.tap.reason.
const SPOOLMAN = 'http://SPOOLMAN_HOST:7912/api/v1';  // Change to your Spoolman address.

const t = msg.tap;
const fail = (reason) => {
    t.success = false;
    t.reason = reason;
    return [null, msg];
};

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    return fail(`Spoolman lookup failed (HTTP ${msg.statusCode})`);
}
const spools = msg.payload;

// Extra field values are JSON-encoded strings, e.g. "\"04-A1-B2-C3-D4-E5-F6\"".
const uidOf = (s) => {
    try {
        const v = JSON.parse((s.extra && s.extra.nfc_uid) || 'null');
        return v ? String(v).trim().toUpperCase() : null;
    } catch (e) {
        return null;
    }
};
const labelOf = (s) => {
    const f = s.filament || {};
    return `#${s.id} ${(f.vendor && f.vendor.name) || ''} ${f.name || ''}`.replace(/\s+/g, ' ').trim();
};
const owners = spools.filter((s) => uidOf(s) === t.tag);

const enrollId = Math.trunc(Number(msg.enroll_id) || 0);
let spool;
let body;
if (enrollId > 0) {
    spool = spools.find((s) => s.id === enrollId);
    if (!spool) return fail(`Enroll: spool #${enrollId} not found (or archived).`);
    const other = owners.find((s) => s.id !== enrollId);
    if (other) {
        return fail(`Enroll: tag ${t.tag} is already on spool ${labelOf(other)}. Clear its nfc_uid in Spoolman first.`);
    }
    body = { location: t.location, extra: { nfc_uid: JSON.stringify(t.tag) } };
    t.mode = 'enroll';
} else {
    if (owners.length === 0) {
        return fail(`Unknown tag ${t.tag} at ${t.location}. To enroll it, set "Spool enroll ID" to the spool's number and tap again.`);
    }
    if (owners.length > 1) {
        return fail(`Tag ${t.tag} is on several spools: ${owners.map(labelOf).join(', ')}. Fix nfc_uid in Spoolman.`);
    }
    spool = owners[0];
    body = { location: t.location };
    t.mode = 'move';
}

t.spool = { id: spool.id, label: labelOf(spool), from: spool.location || 'Unassigned' };
msg.method = 'PATCH';
msg.url = `${SPOOLMAN}/spool/${spool.id}`;
// Replace the GET's response headers, which would otherwise be sent as request headers.
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = body;
return [msg, null];

// Decides success, then fans out:
// output 1: reader feedback (green or red), output 2: reset the enroll helper after
// a successful enroll, output 3: Home Assistant notification for failures.
const t = msg.tap;
if (t.success !== false) {
    if (msg.statusCode === 200) {
        t.success = true;
    } else {
        t.success = false;
        t.reason = `Spoolman update of spool #${t.spool.id} failed (HTTP ${msg.statusCode})`;
    }
}

// Remember the answer so a repeat read of the same tag gets it too.
const last = flow.get('spoolTapLast') || {};
const key = `${t.reader}|${t.tag}`;
if (last[key]) {
    last[key].result = t.success;
    flow.set('spoolTapLast', last);
}

if (t.success) {
    const what = t.mode === 'enroll' ? `tag enrolled, ${t.spool.from} →` : `${t.spool.from} →`;
    node.status({ fill: 'green', shape: 'dot', text: `${t.spool.label}: ${what} ${t.location}` });
} else {
    node.status({ fill: 'red', shape: 'ring', text: t.reason });
    node.warn(t.reason);
}

const feedback = { payload: { action: t.feedbackAction, data: { success: t.success } }, tap: t };
const resetEnroll = t.success && t.mode === 'enroll' ? { payload: {} } : null;
const notify = t.success
    ? null
    : { payload: { data: { title: 'Spool reader', message: t.reason, notification_id: 'spool_reader' } } };
return [feedback, resetEnroll, notify];
